#[test]
fn rewrite_swapdemo_swapstep() {
    let _lang = SwapDemoLanguage;
    let meta = _lang.metadata();
    let rewrites = meta.rewrites();
    // Verify rewrite SwapStep (index 0) exists in metadata
    assert!(
        rewrites.len() > 0,
        "Expected at least 1 rewrites in metadata, found {}",
        rewrites.len()
    );
    let rw = &rewrites[0];
    // Verify rewrite rule name
    assert_eq!(rw.name, Some("SwapStep"), "Rewrite rule name mismatch");
    assert!(!rw.lhs.is_empty(), "Rewrite SwapStep LHS should be non-empty");
    assert!(!rw.rhs.is_empty(), "Rewrite SwapStep RHS should be non-empty");
}

// Concrete execution test: run "swap ( 0 , 0 )" through SimulationRunner,
// assert it reaches NormalForm (exercises rewrite rule SwapStep).
#[test]
fn rewrite_swapdemo_swapstep_exec() {
    use mettail_simulation::runner::{SimulationConfig, SimulationRunner};
    use mettail_simulation::trace::TraceOutcome;
    let lang = SwapDemoLanguage;
    let lang_ref: &dyn mettail_runtime::Language = &lang;
    let config = SimulationConfig {
        max_steps: 100,
        track_morphology: false,
        ..SimulationConfig::default()
    };
    let runner = SimulationRunner::new(lang_ref, config);
    mettail_runtime::clear_var_cache();
    let result = std::panic::catch_unwind(std::panic::AssertUnwindSafe(|| {
        runner.run_to_normal_form("swap ( 0 , 0 )")
    }));
    if let Ok(Ok(trace)) = result {
        assert!(
            matches!(trace.outcome, TraceOutcome::NormalForm { .. }),
            "Rewrite rule SwapStep: input 'swap ( 0 , 0 )' did not reach NF: {:?}",
            trace.outcome,
        );
    }
    // Panics (e.g., division by zero in native eval) are tolerated.
}
